edits.new_text:
# 修改后的文件可能产生不同的 chunk ID。写入新片段前先清理该文件的旧片段，
# 避免函数删除、移动或行号变化后留下无法被 upsert 覆盖的幽灵结果。
# 先通过 get() 获取该文件所有 chunk 的 ID，再按 ID 精确删除，比
# 直接 delete(where=) 更可靠——后者依赖 metadata 过滤，在并发或
# 部分写入失败时可能遗漏残留记录。
if not effective_force:
    for _, rel in files_to_index:
        try:
            results = collection.get(where={"file": rel}, include=[])
            if results and results["ids"]:
                collection.delete(ids=results["ids"])
        except Exception:
            pass
